using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using Unity.Profiling;
public static class RtxDrawCallBenchmark {
 const string Root="Recovery/DrawCalls_20261107/RTX3060";
 static Dictionary<Material,Shader> restoreBindings=new Dictionary<Material,Shader>();static Dictionary<Material,Shader> saved=new Dictionary<Material,Shader>(),original=new Dictionary<Material,Shader>();static Camera camera;static MonoBehaviour movement;static Vector3 position;static Quaternion rotation;static bool moving,background,maximized,finished;static int rate,vsync,phase=-1,lastFrame=-1;static EditorWindow window;static double start,bat,tri;static List<float> times=new List<float>(),gpuTimes=new List<float>();static ProfilerRecorder batches,triangles,gpu;static string csv="view,mode,frames,mean_ms,median_ms,p95_ms,gpu_ms,batches,triangles,width,height,fov\n";static bool captured;static float oldFov;
 static Vector3[] positions={new Vector3(509.513f,2.235f,1248.762f),new Vector3(500,2.235f,1180),new Vector3(465,3,912),new Vector3(452,3,900)};static float[] yaws={180,180,270,90};static string[] modes={"OriginalTrees","InstancedTrees","OriginalRepeat","InstancedRepeat"};
 public static object Run(){if(!EditorApplication.isPlaying)throw new Exception("Play Mode required");if(!SystemInfo.graphicsDeviceName.Contains("RTX 3060"))throw new Exception("Unexpected GPU");Directory.CreateDirectory(Root);File.WriteAllText(Root+"/GPU.txt",SystemInfo.graphicsDeviceName+"\n"+SystemInfo.graphicsDeviceVersion+"\nBatteryStatus="+SystemInfo.batteryStatus);foreach(var line in File.ReadAllLines("Recovery/DrawCalls_20261107/InstalledMaterialShaders.tsv").Skip(1)){if(String.IsNullOrWhiteSpace(line))continue;var p=line.Split('\t');var m=AssetDatabase.LoadAssetAtPath<Material>(p[0]);var a=AssetDatabase.LoadAssetAtPath<Shader>(p[1]);var b=AssetDatabase.LoadAssetAtPath<Shader>(p[2]);if(!m||!a||!b||(m.shader!=a&&m.shader!=b))throw new Exception("Saved material binding mismatch");restoreBindings[m]=m.shader;saved[m]=b;original[m]=a;}if(saved.Count!=10)throw new Exception("Expected10 bindings");var fw=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.FrameDebuggerWindow"));fw.GetType().GetMethod("DisableFrameDebugger",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(fw,null);EditorApplication.isPaused=false;camera=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.name=="Camera");position=camera.transform.position;rotation=camera.transform.rotation;oldFov=camera.fieldOfView;movement=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).FirstOrDefault(m=>m.GetType().Name=="KarakterHareket");moving=movement&&movement.enabled;if(movement)movement.enabled=false;window=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView"));maximized=window.maximized;window.maximized=true;window.Focus();background=Application.runInBackground;rate=Application.targetFrameRate;vsync=QualitySettings.vSyncCount;Application.runInBackground=true;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;batches=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Batches Count",1);triangles=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Triangles Count",1);gpu=ProfilerRecorder.StartNew(ProfilerCategory.Render,"GPU Frame Time",1);EditorApplication.playModeStateChanged+=OnState;Next();EditorApplication.update+=Tick;return "Started4 views x4 phases on RTX3060; 3s warmup +5s sample";}
 static void OnState(PlayModeStateChange s){if(s==PlayModeStateChange.ExitingPlayMode)Finish();}
 static void Finish(){if(finished)return;finished=true;EditorApplication.update-=Tick;EditorApplication.playModeStateChanged-=OnState;foreach(var p in restoreBindings)if(p.Key)p.Key.shader=p.Value;if(camera){camera.transform.SetPositionAndRotation(position,rotation);camera.fieldOfView=oldFov;}if(movement)movement.enabled=moving;if(window)window.maximized=maximized;Application.runInBackground=background;Application.targetFrameRate=rate;QualitySettings.vSyncCount=vsync;batches.Dispose();triangles.Dispose();gpu.Dispose();File.WriteAllText(Root+"/status.txt","COMPLETE; saved optimized shader bindings and camera/control/quality state restored");}
 static void Next(){phase++;if(phase>=positions.Length*modes.Length){Finish();return;}bool optimized=phase%2==1;camera.fieldOfView=60;foreach(var p in saved)p.Key.shader=optimized?p.Value:original[p.Key];camera.transform.SetPositionAndRotation(positions[phase/4],Quaternion.Euler(0,yaws[phase/4],0));times.Clear();gpuTimes.Clear();bat=tri=0;captured=false;start=EditorApplication.timeSinceStartup;File.WriteAllText(Root+"/status.txt",phase/4+" "+modes[phase%4]);}
